using System;
using System.Linq;
using Newtonsoft.Json.Linq;
namespace SpatialWallpaper.Sdk {
 public static class ControlledData {
  public static void Validate(JObject scene){
   int nodes=((JArray)scene["nodes"]).Count,meshes=((JArray)scene["meshes"]).Count,materials=((JArray)scene["materials"]).Count,totalInstances=0,totalBindings=0;var effects=JsonData.Array(scene["effects"],4096);
   foreach(var token in effects){var effect=token as JObject;JsonData.Require(effect!=null,"controlled-object-required");string kind=JsonData.Text(effect["kind"]);JsonData.Integer(effect["node"],0,nodes-1);
    switch(kind){
     case "ambient-gradient":JsonData.Fields(effect,"kind","node","sky","equator","ground");foreach(string color in new[]{"sky","equator","ground"})JsonData.Vector(effect[color],4,0,16);break;
     case "ambient":JsonData.Fields(effect,"kind","node","irradiance");JsonData.Vector(effect["irradiance"],4,0,16);break;
     case "background":JsonData.Fields(effect,"kind","node","color");JsonData.Vector(effect["color"],4,0,16);break;
     case "clip-depth":JsonData.Fields(effect,"kind","node","depth");JsonData.Number(effect["depth"],.001,10000);break;
     case "camera":JsonData.Fields(effect,"kind","node","hdr","msaa","opaque","depth","post","renderer");JsonData.Require((string)effect["renderer"]=="forward"||(string)effect["renderer"]=="forward-plus","camera-renderer");foreach(string key in new[]{"hdr","opaque","depth","post"})JsonData.Require(effect[key]?.Type==JTokenType.Boolean,"camera-boolean");int samples=JsonData.Integer(effect["msaa"],1,4);JsonData.Require(samples==1||samples==2||samples==4,"camera-msaa");break;
     case "oscillation":JsonData.Fields(effect,"kind","node","position","rotation");JsonData.Require((int)scene["nodes"][(int)effect["node"]]["parent"]>=0,"oscillation-root");Harmonics(effect["position"],10);Harmonics(effect["rotation"],180);JsonData.Require(((JArray)effect["position"]).Count+((JArray)effect["rotation"]).Count>0,"empty-oscillation");break;
     case "surface-material":JsonData.Fields(effect,"kind","node","materials","depthPerScale","tiling");JsonData.Number(effect["depthPerScale"],0,100);JsonData.Vector(effect["tiling"],4,-100,100);var surfaceMaterials=JsonData.Array(effect["materials"],64);JsonData.Require(surfaceMaterials.Count>0&&surfaceMaterials.Select(v=>(int)v).Distinct().Count()==surfaceMaterials.Count,"surface-material-uniqueness");foreach(var item in surfaceMaterials){int m=JsonData.Integer(item,0,materials-1);var p=scene["materials"][m]["properties"];bool level=p["_WaterLevel"]!=null,depth=p["_DepthEnd"]!=null;JsonData.Require(level||depth,"surface-properties-required");if(level)foreach(string key in new[]{"_WaterLevel","_WorldScale","_Animation"})Property(p,key,"float");if(depth){Property(p,"_DepthEnd","float");Property(p,"_CausticsEnd","float");Property(p,"_CausticsTiling","vector");}}break;
     case "planar-reflection":JsonData.Fields(effect,"kind","node","material","resolution","excluded");int output=JsonData.Integer(effect["material"],0,materials-1);Property(scene["materials"][output]["properties"],"_ReflectionTex","texture");double resolution=JsonData.Number(effect["resolution"],.25,.5);JsonData.Require(resolution==.25||resolution==.5,"planar-resolution");var excluded=JsonData.Array(effect["excluded"],64);JsonData.Require(excluded.Count>0&&excluded.Select(v=>(int)v).Distinct().Count()==excluded.Count,"planar-excluded-uniqueness");foreach(var item in excluded){int n=JsonData.Integer(item,0,nodes-1);JsonData.Require((int)scene["nodes"][n]["mesh"]>=0,"planar-excluded-renderer");}break;
     case "reflection-probe":JsonData.Fields(effect,"kind","node","resolution","size","center","near","far","shadowDistance","background","intensity","blend","box","importance");JsonData.Require(JsonData.Integer(effect["resolution"],128,128)==128,"probe-resolution");JsonData.Vector(effect["size"],3,.00001,10000);JsonData.Vector(effect["center"],3);double near=JsonData.Number(effect["near"],.00001,100);JsonData.Require(JsonData.Number(effect["far"],.00001,10000)>near,"probe-clip");JsonData.Number(effect["shadowDistance"],0,1000);JsonData.Vector(effect["background"],4,0,16);JsonData.Number(effect["intensity"],0,16);JsonData.Number(effect["blend"],0,10000);JsonData.Require(effect["box"]?.Type==JTokenType.Boolean,"probe-box");JsonData.Integer(effect["importance"],0,64);break;
     case "post":JsonData.Fields(effect,"kind","node","bloom","aces","exposure","saturation","vignette");JsonData.Vector(effect["bloom"],3,0,100);JsonData.Number(effect["bloom"][2],0,1);JsonData.Require(effect["aces"]?.Type==JTokenType.Boolean,"post-aces");JsonData.Number(effect["exposure"],-20,20);JsonData.Number(effect["saturation"],-100,100);JsonData.Vector(effect["vignette"],2,0,1);break;
     case "instances":JsonData.Fields(effect,"kind","node","mesh","materials","positions","scale");JsonData.Integer(effect["mesh"],0,meshes-1);foreach(var m in JsonData.Array(effect["materials"],64))JsonData.Integer(m,0,materials-1);var positions=JsonData.Array(effect["positions"],65536);totalInstances+=positions.Count;JsonData.Require(totalInstances<=100000,"instance-total-limit");foreach(var p in positions)JsonData.Vector(p,3);JsonData.Number(effect["scale"],.00001,10000);break;
     case "light":var lightFields=new[]{"kind","node","type","color","intensity","range","spot","innerSpot","shadows","bias","normalBias","near"};if(effect.ContainsKey("mask")){JsonData.Fields(effect,lightFields.Concat(new[]{"mask"}).ToArray());JsonData.Integer(effect["mask"],int.MinValue,int.MaxValue);}else JsonData.Fields(effect,lightFields);string type=JsonData.Text(effect["type"]);JsonData.Require(type=="point"||type=="spot"||type=="directional","unsupported-light-type");JsonData.Vector(effect["color"],4,0,16);JsonData.Number(effect["intensity"],0,100000);JsonData.Number(effect["range"],.00001,10000);double spot=JsonData.Number(effect["spot"],1,179);JsonData.Number(effect["innerSpot"],0,spot);JsonData.Integer(effect["shadows"],0,2);JsonData.Number(effect["bias"],0,2);JsonData.Number(effect["normalBias"],0,3);JsonData.Number(effect["near"],.00001,10);break;
     case "signal":JsonData.Fields(effect,"kind","node","signal","seed","materials","lights");JsonData.Require((string)effect["signal"]=="flicker"||(string)effect["signal"]=="intermittent","signal-kind");JsonData.Integer(effect["seed"],0,4096);
      var bindings=JsonData.Array(effect["materials"],4096);var lights=JsonData.Array(effect["lights"],4096);totalBindings+=bindings.Count+lights.Count;JsonData.Require(totalBindings<=16384,"signal-binding-limit");
      foreach(JObject b in bindings){JsonData.Fields(b,"material","property","type","basis","gain");int index=JsonData.Integer(b["material"],0,materials-1);string property=JsonData.Text(b["property"],128),binding=JsonData.Text(b["type"]);JsonData.Require(new[]{"float","vector-w","color","time"}.Contains(binding),"signal-binding-type");var target=scene["materials"][index]["properties"][property];JsonData.Require(target!=null&&(string)target["type"]==(binding=="vector-w"?"vector":binding=="time"?"float":binding),"signal-property-type");JsonData.Vector(b["basis"],4);JsonData.Number(b["gain"],-10000,10000);}
      foreach(JObject b in lights){JsonData.Fields(b,"node","intensity");JsonData.Integer(b["node"],0,nodes-1);JsonData.Number(b["intensity"],0,100000);}break;
     default:throw new System.IO.InvalidDataException("unsupported-controlled-kind");
    }
   }
   JsonData.Require(effects.OfType<JObject>().Count(e=>(string)e["kind"]=="background")<=1,"duplicate-background");
   JsonData.Require(effects.OfType<JObject>().Count(e=>(string)e["kind"]=="clip-depth")<=1,"duplicate-clip-depth");
   JsonData.Require(effects.OfType<JObject>().Count(e=>(string)e["kind"]=="camera")<=1,"duplicate-camera");
   foreach(string kind in new[]{"surface-material","planar-reflection","reflection-probe"})JsonData.Require(effects.OfType<JObject>().Count(e=>(string)e["kind"]==kind)<=1,"duplicate-"+kind);
   var oscillations=effects.OfType<JObject>().Where(e=>(string)e["kind"]=="oscillation").ToArray();JsonData.Require(oscillations.Length<=64&&oscillations.Select(e=>(int)e["node"]).Distinct().Count()==oscillations.Length,"oscillation-limit-or-duplicate");
   var lightNodes=new System.Collections.Generic.HashSet<int>();int ambient=0,post=0;foreach(JObject effect in effects){if((string)effect["kind"]=="light")JsonData.Require(lightNodes.Add((int)effect["node"]),"duplicate-light-node");if((string)effect["kind"]=="ambient"||(string)effect["kind"]=="ambient-gradient")JsonData.Require(++ambient==1,"duplicate-ambient");if((string)effect["kind"]=="post")JsonData.Require(++post==1,"duplicate-post");}foreach(JObject effect in effects)if((string)effect["kind"]=="signal")foreach(var binding in (JArray)effect["lights"])JsonData.Require(lightNodes.Contains((int)binding["node"]),"signal-light-reference");
  }
  static void Property(JToken properties,string key,string type)=>JsonData.Require((string)properties[key]?["type"]==type,"controlled-property-type");
  static void Harmonics(JToken value,double amplitude){foreach(var item in JsonData.Array(value,2)){var h=item as JObject;JsonData.Require(h!=null,"harmonic-object");JsonData.Fields(h,"amplitude","frequency","phase");JsonData.Vector(h["amplitude"],3,-amplitude,amplitude);JsonData.Vector(h["frequency"],3,0,32);JsonData.Vector(h["phase"],3,-Math.PI*2,Math.PI*2);}}
 }
}
